import {scenarios,contexts,notes} from './scenarios.js';
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chapters=[...document.querySelectorAll('.chapter')];
const names=['소개','검증 배경','시나리오','검증 범위','발표 자료'];
let selected=0,step=0,contextIndex=1,chapter=0,presenting=false,lastFocus=null,toastTimer;
const pad=n=>String(n).padStart(2,'0');
const concert=`<div class="concert-cover"><small>ORBIT LIVE / FICTIONAL CONCERT</small><strong>STELLAR NIGHT</strong></div>`;
const simHead=`<div class="sim-header"><strong>Orbit tickets</strong><span>DEMO EXPERIENCE</span></div>`;
function seatMap(mode){let html='<div class="sim-stage">S T A G E</div><div class="seat-grid">';for(let i=0;i<32;i++){let target=i===6,alt=i===7;let cls='seat';if((mode==='alternative'&&alt)||(target&&['seats','claimed'].includes(mode)))cls+=' selected';if([2,12,13,21,29].includes(i)||(target&&['conflict','alternative'].includes(mode)))cls+=' taken';html+=`<span class="${cls}">${target?'A7':alt?'A8':''}</span>`;}return html+'</div><div class="seat-legend"><span>□ 선택 가능</span><span>■ 선택 좌석</span><span>▧ 선택 불가</span></div>';}
function renderScreen(screen){let html='';
 if(screen==='concert')html=`${concert}<h4>별빛 아래, 우리의 밤</h4><p class="sim-meta">2026. 10. 24 SAT · 19:00<br>ORBIT HALL · 예시 공연 · 88,000원</p><div class="sim-action highlight">예매하기</div>`;
 else if(['seats','available','claimed','conflict','alternative'].includes(screen)){const conflict=screen==='conflict',alt=screen==='alternative';html=`<p class="sim-meta">STELLAR NIGHT / 좌석 선택</p><h4>${screen==='available'?'같은 좌석, 두 명의 관객':screen==='claimed'?'관객 A · 좌석 확보 완료':alt?'관객 B · 다른 좌석 선택':conflict?'관객 B · 좌석 확보 요청':'어느 자리에서 만나볼까요?'}</h4>${seatMap(screen)}${conflict?'<div class="sim-notice error highlight">이미 다른 관객이 확보한 좌석입니다.<br>다른 좌석을 선택해 주세요.</div><div class="sim-action muted-action">결제 진행 불가</div>':`<div class="ticket-summary"><span>${screen==='available'?'A와 B가 보고 있는 좌석':'선택한 좌석'}</span><strong>${alt?'A-08':'A-07'}</strong></div><div class="sim-action ${screen==='available'?'':'highlight'}">${screen==='available'?'관객 A · 관객 B / 독립된 세션':screen==='claimed'?'A-07 좌석 확보됨':`${alt?'A-08':'A-07'} · 88,000원`}</div>`}`;}
 else if(['checkout','payment-error','retry'].includes(screen)){const failed=screen==='payment-error',retry=screen==='retry';html=`<p class="sim-meta">STELLAR NIGHT / 결제</p><h4>${failed?'결제를 완료하지 못했어요':retry?'다른 수단으로 다시 시도해요':'예매 내용을 확인해 주세요'}</h4><div class="ticket-summary"><span>선택 좌석</span><strong>A열 7번 · 1매</strong></div><div class="ticket-summary"><span>결제 금액</span><strong>88,000원</strong></div><div class="ticket-summary ${retry?'highlight':''}"><span>결제 수단</span><strong>${retry?'다른 카드':'신용카드'}</strong></div>${failed?'<div class="sim-notice error highlight">카드 승인이 거절되었습니다.<br>결제 수단을 확인한 후 다시 시도해 주세요.</div>':retry?'<div class="sim-notice">좌석 확보가 유효한 동안 다시 시도할 수 있습니다.</div>':'<div class="sim-notice">결제 요청을 처리하고 있습니다.<br>버튼을 다시 누를 수 없습니다.</div>'}<div class="sim-action ${failed||retry?'highlight':'muted-action'}">${failed?'다른 결제 수단 선택':retry?'88,000원 다시 결제하기':'처리 중 · 중복 요청 방지'}</div>`;}
 else html=`<div class="sim-complete"><div class="checkmark">✦</div><h4>${screen==='ticket'?'나의 티켓을 다시 만나다':'예매가 완료되었습니다'}</h4><p class="sim-meta">${screen==='ticket'?'다시 조회해도 같은 예매 내역입니다.':'공연장에서 만나요.'}</p><div class="ticket highlight"><strong>STELLAR NIGHT</strong><div class="ticket-meta"><span>2026.10.24 · 19:00</span><span>A열 7번</span></div><div class="ticket-summary"><span>예시 예매 번호</span><b>ORB-DEMO-001</b></div><p class="sim-meta">가상 티켓 · 실제 입장에 사용할 수 없습니다</p></div><div class="sim-action">예매 내역 1건</div></div>`;
 $('#simulation').innerHTML=simHead+`<div class="sim-body" data-screen="${screen}">${html}</div>`;
}
function renderScenario(){const s=scenarios[selected],st=s.steps[step];$('#scenario-category').textContent=s.category;$('#scenario-title').textContent=s.title;$('#scenario-description').textContent=s.description;$('#scenario-tabs').innerHTML=scenarios.map((s,i)=>`<button class="scenario-tab" data-scenario="${i}" aria-pressed="${i===selected}"><span>${pad(i+1)}</span>${s.label}</button>`).join('');$('#step-count').textContent=`STEP ${pad(step+1)} / ${pad(s.steps.length)}`;$('#step-progress').innerHTML=s.steps.map((_,i)=>`<span class="${i===step?'current':i<step?'done':''}"></span>`).join('');$('#step-copy').innerHTML=`<h4>${st.title}</h4><p>${st.action}<br>${st.expected}</p><div class="assertion"><span>이 단계에서 확인할 내용</span>${st.assertion}</div>`;$('#step-prev').disabled=step===0;$('#step-next').disabled=step===s.steps.length-1;$('#step-next').textContent=step===s.steps.length-1?'마지막 단계':'다음 단계 →';renderScreen(st.screen);}
function selectScenario(i){selected=i;step=0;renderScenario();}
function advanceStep(n){step=Math.max(0,Math.min(scenarios[selected].steps.length-1,step+n));renderScenario();}
$('#scenario-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-scenario]');if(b)selectScenario(Number(b.dataset.scenario));});
$('#step-prev').onclick=()=>advanceStep(-1);$('#step-next').onclick=()=>advanceStep(1);$('#reset').onclick=()=>{step=0;renderScenario();};
function renderContexts(){$('#context-cards').innerHTML=[(contextIndex+2)%3,contextIndex,(contextIndex+1)%3].map(i=>{const c=contexts[i];return `<button class="context-card ${i===contextIndex?'active':''}" data-context="${i}" aria-pressed="${i===contextIndex}"><small>${c.english}</small><h3>${c.title}</h3><span class="card-image"></span><span class="card-number">${pad(i+1)}</span></button>`;}).join('');$('#context-count').textContent=`${pad(contextIndex+1)} / 03`;$('#context-description').textContent=contexts[contextIndex].description;}
$('#context-cards').onclick=e=>{const b=e.target.closest('[data-context]');if(b){contextIndex=Number(b.dataset.context);renderContexts();}};
$('#context-prev').onclick=()=>{contextIndex=(contextIndex+2)%3;renderContexts();};$('#context-next').onclick=()=>{contextIndex=(contextIndex+1)%3;renderContexts();};
$('#result-list').innerHTML=scenarios.map((s,i)=>`<button class="result-row" data-result="${i}"><span class="result-num">${pad(i+1)}</span><div><h3>${s.label}</h3><p>${s.risk}을 살펴봅니다</p></div><span class="status">${s.status}</span><span>↗</span></button>`).join('');
$('#result-list').onclick=e=>{const b=e.target.closest('[data-result]');if(b){selectScenario(Number(b.dataset.result));goChapter(2);}};
function openModal(kicker,html){lastFocus=document.activeElement;$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;$('#modal').showModal();$('#modal').scrollTop=0;$('#modal-close').focus();}
function showNotes(){openModal('PRESENTER NOTES / ABOUT 7 MINUTES',`<h2>별빛을 따라, 사용자 여정의 끝까지</h2><p class="modal-note">예시 시나리오 기준 발표 대본입니다. 단계 진행은 시뮬레이션이며 실제 테스트 실행이 아닙니다.</p>${notes.map(n=>`<section class="notes-block"><h3>${n.title}</h3><small>${n.time}</small><p>${n.text}</p></section>`).join('')}`);}
function showEvidence(){const s=scenarios[selected];openModal('SCENARIO BLUEPRINT / NOT EXECUTED',`<h2>${s.label} · 검증 설계</h2><p class="modal-note">교육용 가상 시나리오입니다. 회사 코드와 실행 보고서가 없어 파일 경로·통과 여부를 제시하지 않습니다.</p><h3>확인할 내용</h3><ul>${s.checks.map(c=>`<li>${c}</li>`).join('')}</ul><h3>사용자 행동 → 기대 결과</h3><pre>${escape(s.blueprint)}</pre><h3>실제 프로젝트에서 연결할 자료</h3><p>화면과 API의 구현 파일, E2E 테스트와 assertion, 테스트 데이터와 환경, 실행 시각 및 보고서가 필요합니다. 회사 환경에서 원샷 프롬프트를 실행해 연결할 수 있습니다.</p><a class="primary-button download-link" href="scenarios.js" download>예시 시나리오 데이터 다운로드 ↓</a>`);}
$('#notes-open').onclick=showNotes;$('#resource-notes').onclick=showNotes;$('#evidence-open').onclick=showEvidence;$('#resource-design').onclick=showEvidence;$('#modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>lastFocus?.focus());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
function syncChapter(){let nearest=0,min=Infinity;chapters.forEach((el,i)=>{let d=Math.abs(el.getBoundingClientRect().top-76);if(d<min){min=d;nearest=i;}});chapter=nearest;document.querySelectorAll('.header nav a').forEach((a,i)=>{a.classList.toggle('active',i===chapter);if(i===chapter)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});$('#chapter-count').textContent=`${pad(chapter+1)} / 05`;$('#chapter-name').textContent=names[chapter];$('#chapter-prev').disabled=chapter===0;$('#chapter-next').disabled=chapter===4;}
let scrollPending=false;window.addEventListener('scroll',()=>{if(!scrollPending){requestAnimationFrame(()=>{syncChapter();scrollPending=false;});scrollPending=true;}},{passive:true});
function goChapter(i){chapters[Math.max(0,Math.min(4,i))].scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function setPresentation(on){presenting=on;document.body.classList.toggle('presenting',on);$('#presentation-bar').hidden=!on;$('#present').setAttribute('aria-pressed',String(on));$('#present').innerHTML=on?'발표 중 <span>✦</span>':'발표 모드 <span>↗</span>';syncChapter();if(on)toast('← → 단계 이동 · PageUp / PageDown 장면 이동 · Esc 종료');}
$('#present').onclick=()=>setPresentation(!presenting);$('#exit-present').onclick=()=>setPresentation(false);$('#chapter-prev').onclick=()=>goChapter(chapter-1);$('#chapter-next').onclick=()=>goChapter(chapter+1);
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);}
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('전체화면을 지원하지 않는 환경입니다. 발표 모드는 계속 사용할 수 있습니다.');}};
document.addEventListener('fullscreenchange',()=>$('#fullscreen').setAttribute('aria-label',document.fullscreenElement?'전체화면 종료':'전체화면'));
document.addEventListener('keydown',e=>{if($('#modal').open||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;if(!presenting)return;if(e.key==='Escape'){setPresentation(false);return;}if(['ArrowRight','ArrowLeft','PageDown','PageUp','Home','End'].includes(e.key)){e.preventDefault();syncChapter();if(e.key==='Home')goChapter(0);else if(e.key==='End')goChapter(4);else if(e.key==='PageDown')goChapter(chapter+1);else if(e.key==='PageUp')goChapter(chapter-1);else if(chapter===2)advanceStep(e.key==='ArrowRight'?1:-1);else goChapter(chapter+(e.key==='ArrowRight'?1:-1));}});
const starfield=document.createElement('div');starfield.className='starfield';starfield.setAttribute('aria-hidden','true');starfield.innerHTML=Array.from({length:48},(_,i)=>`<i class="star ${i%9===0?'bright':''}" style="--x:${((i*137.508)%100).toFixed(2)}%;--y:${((i*73.913)%100).toFixed(2)}%;--delay:${-(i%13)}s;--duration:${5+i%7}s"></i>`).join('');$('.hero').prepend(starfield);
renderScenario();renderContexts();syncChapter();
